import json, re, datetime

AYLAR = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
BIR = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
ON = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
RAKAM = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
SIRA = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']


def uc(n):
    s = []
    y = n // 100
    if y == 1:
        s.append('yüz')
    elif y > 1:
        s.append(BIR[y] + ' yüz')
    t = (n % 100) // 10
    if t:
        s.append(ON[t])
    b = n % 10
    if b:
        s.append(BIR[b])
    return ' '.join(s)


def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q = n // val
        if q:
            if val == 1000 and q == 1:
                parts.append('bin')
            else:
                parts.append(uc(q) + ' ' + name)
            n = n % val
    if n:
        parts.append(uc(n))
    return ' '.join(parts)


def money(v, cur):
    try:
        v = float(v)
    except Exception:
        return ''
    cents = int(round(abs(v) * 100))
    main, sub = cents // 100, cents % 100
    if cur == 'TL':
        if sub:
            return words(main) + ' lira ' + words(sub) + ' kuruş'
        return words(main) + ' Türk Lirası'
    nm = 'Dolar' if cur == 'USD' else ('Euro' if cur == 'EUR' else 'İngiliz Sterlini')
    sn = 'peni' if cur == 'GBP' else 'sent'
    if sub:
        return words(main) + ' ' + nm + ' ' + words(sub) + ' ' + sn
    return words(main) + ' ' + nm


def digits_spoken(d):
    return ' '.join(RAKAM[int(c)] for c in str(d) if c.isdigit())


def pdate(s):
    try:
        s = str(s).strip()
        if re.match(r'^\d{2}\.\d{2}\.\d{4}$', s):
            return datetime.date(int(s[6:10]), int(s[3:5]), int(s[0:2]))
    except Exception:
        pass
    return None


def sdate(d):
    if not d:
        return ''
    return str(d.day) + ' ' + AYLAR[d.month] + ' ' + str(d.year)


def today(vars):
    try:
        return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        return datetime.date.today()


def jl(x):
    if isinstance(x, (list, dict)):
        return x
    if isinstance(x, str) and x.strip()[:1] in ('[', '{'):
        try:
            return json.loads(x)
        except Exception:
            try:
                import ast
                return ast.literal_eval(x)
            except Exception:
                return None
    return None


def getp(vars, mapped, prefix, path):
    """Read path (dot list) from mapped var (dict/json) or flattened keys prefix.path."""
    obj = jl(vars.get(mapped))
    cur = obj
    ok = True
    for p in path.split('.'):
        if isinstance(cur, dict) and p in cur:
            cur = cur[p]
        elif isinstance(cur, list) and p.isdigit() and int(p) < len(cur):
            cur = cur[int(p)]
        else:
            ok = False
            break
    if ok and obj is not None:
        return cur
    k = prefix + '.' + path
    if k in vars:
        return vars.get(k)
    return None


def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0


def norm(s):
    s = str(s or '').replace('İ', 'i').replace('I', 'ı').lower()
    s = re.sub(r'[^\wçğıöşü ]', ' ', s)
    return ' '.join(s.split())


def okname(n):
    n = str(n or '').strip()
    if not n or len(n) > 30 or 'talimat' in n.lower():
        return ''
    return n


def load_cards(vars):
    c = jl(vars.get('cards_json'))
    if isinstance(c, list):
        return c
    return []

try:
    ex_ = str(vars.get('pdf_exit') or vars.get('send_pdf_response.data.data.exitState') or '')
    rc = str(vars.get('pdf_rc') or vars.get('send_pdf_response.data.result.returnCode') or '')
    vars['pdf_state'] = 'ok' if (ex_.upper() == 'DONE' or rc == '1') else 'fail'
    vars['done_text'] = 'Ekstreniz kayıtlı e-posta adresinize gönderildi.'
    vars['post_action'] = ''
except Exception as e:
    vars["err_check_pdf"] = str(e)[:200]

