try:
    cards = load_cards(vars)
    pick = str(vars.get('card_pick') or '').strip()
    vars['card_pick'] = ''
    tries = int(num(vars.get('card_tries')))
    dg = re.sub(r'\D', '', pick)
    res = 'retry'
    hint = ''
    cand = []
    def allnames():
        ns = [ (c['name'] or ('sonu ' + digits_spoken(c['l4']) + ' ile biten kartınız')) for c in cards if c['main']]
        return ', '.join(ns)
    amb = jl(vars.get('amb_nums')) or []
    vars['amb_nums'] = '[]'
    ambc = [c for c in cards if c['num'] in amb]
    narrowed = []
    if ambc and len(dg) >= 3:
        for c in ambc:
            cd = re.sub(r'\D', '', c['num'])
            f6 = cd[:6]
            if len(dg) >= 10 and dg[:6] == f6 and dg[-4:] == c['l4']:
                narrowed.append(c)
            elif len(dg) <= 6 and f6.startswith(dg):
                narrowed.append(c)
    if len(narrowed) == 1:
        cand = narrowed
        res = 'one'
    elif pick.upper().startswith('HEPS') or norm(pick) in ('hepsi', 'tümü', 'bütün kartlarım', 'hepsini'):
        tries += 1
        hint = 'Borç bilgisini kart kart verebiliyorum. Hangi kartınızın borcunu öğrenmek istersiniz? ' + vars.get('card_examples', '')
    elif len(dg) >= 4:
        cand = [c for c in cards if c['l4'] == dg[-4:]]
        if len(dg) >= 15 and len(cand) > 1:
            c2 = [c for c in cand if re.sub(r'\D', '', c['num'])[:6] == dg[:6]]
            if c2:
                cand = c2
        if len(cand) == 1:
            res = 'one'
        elif len(cand) > 1:
            vars['amb_nums'] = json.dumps([c['num'] for c in cand])
            if len(dg) >= 6:
                hint = 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
            else:
                hint = 'Son dört hanesi ' + digits_spoken(dg[-4:]) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
        else:
            tries += 1
            hint = 'Bu numarayla eşleşen bir kartınız bulunmuyor. Kartlarınız: ' + allnames() + '. Hangisinin borcunu öğrenmek istersiniz?'
    else:
        p = norm(pick)
        cand = [c for c in cards if c['name'] and norm(c['name']) == p]
        if not cand:
