        name = vars.get('sel_name') or ''
        l4w = digits_spoken(l4)
        head = 'Sonu ' + l4w + ' ile biten ' + (name + ' kartınız' if name else 'kartınız')
        sd = pdate(g('statementDate'))
        due = pdate(g('lastPayDate'))
        nsd = pdate(g('nextStatementDate'))
        ndue = pdate(g('nextLastPayDate'))
        vars['stmt_date'] = str(g('statementDate') or '')
        out = []
        top = str(g('statementPaymentStatus') or '')
        names = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
        blocks = []
        for cur in ('TL', 'USD', 'EUR', 'GBP'):
            b = g('debt' + cur)
            present = b is not None or g('debt' + cur + '.statementDebt') is not None
            if not present:
                continue
            def f(k, cur=cur):
                return num(g('debt' + cur + '.' + k))
            has = f('remainingDebt') > 0 or (str(g('debt' + cur + '.statementPaymentStatus')) == 'HAS_DEBT' and f('statementDebt') > 0)
            blocks.append((cur, has, f))
        anydebt = any(h for _, h, _ in blocks)
        if sd is None:
            out.append(head + ' için henüz kesilmiş bir ekstre bulunmuyor; ekstre borcunuz bulunmamaktadır.')
        elif top == 'NO_DEBT' or not anydebt:
            s = head + 'ın ' + sdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
            tot = 0.0
            for cur, h, f in blocks:
                if cur == 'TL':
                    tot = f('totalDebt')
            if tot > 0:
                s += ' Gelecek dönemler dahil toplam borcunuz ' + money(tot, 'TL') + 'dır.'
            dd = due if (due and due >= t) else ndue
            if dd:
                s += ' Son ödeme tarihiniz ' + sdate(dd) + ' olacaktır.'
            out.append(s)
        else:
            intro = head + 'a ait ' + sdate(sd) + ' tarihinde kesilen ekstre '
            first = True
            clear = []
            for cur, h, f in blocks:
                if not h:
                    clear.append(names[cur])
                    continue
                if cur == 'TL':
                    X, Z, Y, T = money(f('statementDebt'), 'TL'), money(f('minPayment'), 'TL'), money(f('remainingDebt'), 'TL'), money(f('remainingMinPayment'), 'TL')
                    rm, mp = f('remainingMinPayment'), f('minPayment')
                    if rm <= 0:
                        s = 'Türk Lirası borcunuz ' + X + ', kalan toplam borcunuz ' + Y + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                    elif rm >= mp:
                        s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + '.'
                    else:
                        s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + ', kalan toplam borcunuz ' + Y + ', kalan minimum ödeme tutarınız ' + T + '.'
                else:
                    s = names[cur] + ' borcunuz ' + money(f('statementDebt'), cur) + ', kalan toplam borcunuz ' + money(f('remainingDebt'), cur) + ', ödenmesi gereken minimum tutar ' + money(f('minPayment'), cur) + '.'
                if first:
                    s = intro + s
                    first = False
                out.append(s)
            if clear:
                if len(clear) == 1:
                    cs = clear[0]
                else:
                    cs = ', '.join(clear[:-1]) + ' ve ' + clear[-1]
                out.append(cs + ' borcunuz bulunmamaktadır.')
            if due and due < t:
                if str(g('automaticPaymentFlag')) == 'Y':
                    for cur, h, f in blocks:
                        if cur == 'TL' and f('remainAutomaticPaymentAmount') > 0:
                            out.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + money(f('remainAutomaticPaymentAmount'), 'TL') + '.')
                out.append('Son ödeme tarihiniz ' + sdate(due) + ' tarihinde geçti.')
                for cur, h, f in blocks:
                    if f('totalDebt') > 0:
                        out.append(names[cur] + ' cinsinden güncel toplam borcunuz ' + money(f('totalDebt'), cur) + '.')
            elif due and due == t:
                out.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            elif due:
                out.append('Borçlarınız için son ödeme tarihiniz ' + sdate(due) + '.')
        vars['reading_text'] = ' '.join(out)
        rd = jl(vars.get('cards_read')) or []
        if vars.get('sel_num') not in rd:
            rd.append(vars.get('sel_num'))
        vars['cards_read'] = json.dumps(rd)
        cards = load_cards(vars)
        left = [c for c in cards if c['main'] and c['num'] not in rd]
        vars['more_cards'] = 'yes' if left else 'no'
except Exception as e:
    vars["err_prep_balance"] = str(e)[:200]

